# Kaggle script kernel (CPU): python-random divergences under torch.compile, on torch 2.14.0 then nightly (self-contained).
import base64, subprocess, sys
open("minimal_verified.py", "wb").write(base64.b64decode(""))
open("diag_random_compile.py", "wb").write(base64.b64decode(""))
subprocess.run(["pip", "-q", "install", "torch==2.14.0", "--index-url", "https://download.pytorch.org/whl/cpu"])
subprocess.run([sys.executable, "minimal_verified.py"])
subprocess.run([sys.executable, "diag_random_compile.py"])
subprocess.run(["pip", "-q", "install", "--pre", "--upgrade", "torch", "--index-url", "https://download.pytorch.org/whl/nightly/cpu"])
subprocess.run([sys.executable, "minimal_verified.py"])
subprocess.run([sys.executable, "diag_random_compile.py"])
print("JOB DONE", flush=True)
